SELECT u.model, quantile(0.5)(r.upstream_response_time_s) as p50_latency FROM llm_gateway.request_log r ASOF LEFT JOIN llm_gateway.usage_log u ON r.request_id = u.request_id AND r.timestamp >= u.timestamp WHERE {{ time_filter('r.timestamp') }} AND r.upstream_response_time_s > 0 AND u.model != '' AND coalesce(nullIf(r.key_id,''), nullIf(r.api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) AND u.model IN ({{ gf_str_multi('model') }}) GROUP BY u.model ORDER BY p50_latency DESC LIMIT 20